  "type": "function",
  "description": "Parse a mailbox string containing one or more email addresses (see RFC 5322, section 3.4).",
  "async": "callback",
  "parameters": [
    {
      "type": "string",
      "name": "mailboxString",
      "description": "The string to be parsed (e.g. <var>User <user@example.com>, other-user@example.com</var>)"
    },
    {
      "name": "options",
      "optional": true,
      "choices": [
        {
          "type": "boolean",
          "deprecated": "Specify the options object instead of a plain boolean to preserve groups.",
          "description": "Keep grouped hierarchies. Groups may be specified in a mailbox string as follows: <var>GroupName : user1 <user1@example.com>, user2@example,com ;</var>."
        },
        {
          "type": "object",
          "properties": {
            "preserveGroups": {
              "type": "boolean",
              "optional": true,
              "description": "Keep grouped hierarchies. Groups may be specified in a mailbox string as follows: <var>GroupName : user1 <user1@example.com>, user2@example,com ;</var>."
            },
            "expandMailingLists": {
              "type": "boolean",
              "optional": true,
              "permissions": ["addressBooks"],
              "description": "Expand Thunderbird mailing lists (specified as <var>ListName <ListName></var>) and include the parsed primary email addresses of all members. When used together with <var>preserveGroups</var>, the mailing list's name and hierarchy are preserved. If the mailing list does not exist, or the <permission>addressBook</permission> permission is not granted, the entries are not expanded and returned unchanged."
            }
          }
        }
      ]
    },
    {
      "type": "function",
      "name": "callback",
      "optional": true,
      "parameters": [
        {
          "type": "array",
          "items": {
            "$ref": "messengerUtilities.ParsedMailbox"
          }
        }
      ]
    }
  ]
},
